// Promo gate: max 3 promos per customer per local calendar day, and at least
// 2 hours between two promos to the same customer. Security pushes are never
// limited and never counted. State is in memory (single process).

const MAX_PROMOS_PER_DAY = 3;
const MIN_GAP_MS = 2 * 60 * 60 * 1000;
// Records older than this cannot affect a decision: a local day is at most
// ~25h long and the gap is 2h.
const RETAIN_MS = 72 * 60 * 60 * 1000;

const formatters = new Map();

function localDay(timeZone, ms) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    });
    formatters.set(timeZone, f);
  }
  return f.format(ms); // e.g. "2026-10-23"
}

export function createGate() {
  const promosByUser = new Map(); // userId -> [{ id, t }]
  const owner = new Map(); // id -> userId (promo ids only)
  let seq = 0;

  const deny = (rule) => ({ allowed: false, rule, id: null });

  function request({ userId, timeZone, category, now }) {
    if (category === 'security') {
      return { allowed: true, rule: '', id: `s${++seq}` };
    }
    if (category !== 'promo') return deny('unknown-category');

    const ms = now instanceof Date ? now.getTime() : NaN;
    if (!Number.isFinite(ms)) return deny('invalid-time');

    let today;
    try {
      today = localDay(timeZone, ms);
    } catch {
      return deny('invalid-time-zone');
    }

    let list = promosByUser.get(userId);
    if (list) {
      list = list.filter((r) => {
        if (r.t >= ms - RETAIN_MS) return true;
        owner.delete(r.id);
        return false;
      });
      promosByUser.set(userId, list);
    } else {
      list = [];
      promosByUser.set(userId, list);
    }

    // Day is judged in the timezone given on this request.
    let count = 0;
    for (const r of list) if (localDay(timeZone, r.t) === today) count++;
    if (count >= MAX_PROMOS_PER_DAY) return deny('daily-cap');

    for (const r of list) {
      if (Math.abs(ms - r.t) < MIN_GAP_MS) return deny('min-gap');
    }

    const id = `p${++seq}`;
    list.push({ id, t: ms });
    owner.set(id, userId);
    return { allowed: true, rule: '', id };
  }

  function cancel(id) {
    const userId = owner.get(id);
    if (userId === undefined) return;
    owner.delete(id);
    const list = promosByUser.get(userId);
    if (!list) return;
    const i = list.findIndex((r) => r.id === id);
    if (i !== -1) list.splice(i, 1);
  }

  return { request, cancel };
}

import assert from 'node:assert/strict';
import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/courier-d2-2/bot.mjs';

const LA = 'America/Los_Angeles';
const d = (s) => new Date(s);
const req = (g, o) => g.request({ userId: 'u', timeZone: LA, category: 'promo', ...o });

// gap + cap, LA (UTC-7 in Oct): local day Oct 23 = 07:00Z Oct 23 .. 07:00Z Oct 24
let g = createGate();
let r1 = req(g, { now: d('2026-10-23T08:00:00Z') });
assert.equal(r1.allowed, true); assert.equal(r1.rule, ''); assert.ok(r1.id);
let r = req(g, { now: d('2026-10-23T09:59:59Z') });
assert.deepEqual(r, { allowed: false, rule: 'min-gap', id: null });
assert.equal(req(g, { now: d('2026-10-23T10:00:00Z') }).allowed, true);
assert.equal(req(g, { now: d('2026-10-23T12:00:00Z') }).allowed, true);
assert.equal(req(g, { now: d('2026-10-23T20:00:00Z') }).rule, 'daily-cap');
// just before local midnight still capped, after midnight allowed
assert.equal(req(g, { now: d('2026-10-24T06:59:00Z') }).rule, 'daily-cap');
assert.equal(req(g, { now: d('2026-10-24T07:00:00Z') }).allowed, true);

// security never limited, doesn't count
g = createGate();
for (let i = 0; i < 10; i++) assert.equal(g.request({ userId: 'u', timeZone: LA, category: 'security', now: d('2026-10-23T08:00:00Z') }).allowed, true);
assert.equal(req(g, { now: d('2026-10-23T08:00:00Z') }).allowed, true);

// cancel frees cap and gap; double cancel / unknown harmless
g = createGate();
const a = req(g, { now: d('2026-10-23T08:00:00Z') });
assert.equal(req(g, { now: d('2026-10-23T08:30:00Z') }).rule, 'min-gap');
g.cancel(a.id); g.cancel(a.id); g.cancel('nope');
assert.equal(req(g, { now: d('2026-10-23T08:30:00Z') }).allowed, true);

// per-user and per-timezone day boundaries: Berlin vs LA
g = createGate();
const B = 'Europe/Berlin'; // UTC+2 on Oct 23
for (const h of [0, 2, 4]) assert.equal(g.request({ userId: 'b', timeZone: B, category: 'promo', now: d(`2026-10-23T0${h}:00:00Z`) }).allowed, true);
assert.equal(g.request({ userId: 'b', timeZone: B, category: 'promo', now: d('2026-10-23T10:00:00Z') }).rule, 'daily-cap');
assert.equal(g.request({ userId: 'other', timeZone: B, category: 'promo', now: d('2026-10-23T10:00:00Z') }).allowed, true);
// 22:00Z Oct 23 = midnight Oct 24 Berlin -> new day
assert.equal(g.request({ userId: 'b', timeZone: B, category: 'promo', now: d('2026-10-23T22:00:00Z') }).allowed, true);

// DST fall-back day in LA (Nov 1 2026, 25h): day runs 07:00Z Nov 1 .. 08:00Z Nov 2
g = createGate();
for (const t of ['07:00', '09:00', '11:00']) assert.equal(req(g, { now: d(`2026-11-01T${t}:00Z`) }).allowed, true);
assert.equal(req(g, { now: d('2026-11-02T07:30:00Z') }).rule, 'daily-cap');
assert.equal(req(g, { now: d('2026-11-02T08:00:00Z') }).allowed, true);

console.log('all ok');
